-- Koppelt elke nieuwe demo-gebruiker aan de bijbehorende standaardgroep
-- (Specialisten/Laboranten/Bekijkers), dezelfde mapping als
-- sql/herstel_ontbrekende_tabellen.sql voor de allereerste seed gebruikt.
SELECT u.id, g.id FROM users u JOIN groepen g ON
  (u.rol = 'specialist' AND g.naam = 'Specialisten') OR
  (u.rol = 'laborant' AND g.naam = 'Laboranten') OR
  (u.rol = 'bekijker' AND g.naam = 'Bekijkers')
WHERE u.email IN ('anna.devries@demo.stocuro.test', 'f.vandijk@demo.stocuro.test', 'i.peters@demo.stocuro.test', 'eva.smit@demo.stocuro.test');

